import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {createGame as createRawGame,step,startStage,BOSSES,SKILL_KITS,isInsideHazard,getDomainGuide,getPatternGuide,getTakeoverView,sweptBladeCollision,sweptPursuitCollision} from './engine.js';

// Unit combat fixtures consume the new first-act entrance; explicit intro tests use createRawGame.
function createGame(options={}){const s=createRawGame(options);if(s.cinematic?.kind==='bossIntro')finishCut(s);return s;}
function finishCut(s,input={}){for(let i=0;i<300&&s.cinematic;i++)step(s,input);return s;}
function tick(s,input={},seconds=1){for(let t=0;t<seconds;t+=1/60)step(s,input,1/60);return s;}
const bossIndex=id=>BOSSES.findIndex(b=>b.id===id);
function duel(stage=bossIndex('gojo'),character='director'){const s=createGame({stage,character,skipIntro:true});s.player.x=700;s.player.y=500;s.boss.x=780;s.boss.y=500;s.boss.patternCooldown=99;return s;}
test('same seed and inputs produce identical complete state',()=>{const a=createGame({seed:817}),b=createGame({seed:817});for(let i=0;i<900;i++){const input={right:i<200,attack:true,skill:i%150===0,dodge:i%180===0,swap:i===500};step(a,input,1/60);step(b,input,1/60);}assert.deepEqual(a,b);});
test('basic attack damages a nearby target and generates hype',()=>{const s=duel();tick(s,{attack:true},1);assert.ok(s.boss.hp<s.boss.maxHp-60);assert.ok(s.player.hype>0);assert.ok(s.stats.hits>=3);});
test('W uses cooldown only and cannot repeat during recovery',()=>{const s=duel();s.player.energy=0;step(s,{skill:true});assert.equal(s.stats.skills,1);assert.equal(s.player.cooldowns.skill,SKILL_KITS.director.w.cooldown);const hp=s.boss.hp;tick(s,{skill:true},1);assert.equal(s.stats.skills,1);assert.equal(s.boss.hp,hp);});
test('run character stays fixed despite legacy swap and role inputs',()=>{for(const character of ['director','actor']){const s=duel(0,character);s.player.hp=123;tick(s,{swap:true,role:true},2);assert.equal(s.player.character,character);assert.equal(s.runCharacter,character);assert.equal(s.player.role,'sword');assert.equal(s.stats.swaps,0);startStage(s,1);assert.equal(s.player.character,character);}});
test('W and E cooldowns are independent and neither consumes energy',()=>{for(const character of ['director','actor']){const s=duel(0,character);s.player.energy=0;step(s,{skill:true,buff:true});assert.equal(s.stats.skills,1);assert.equal(s.stats.buffs,1);assert.equal(s.player.cooldowns.skill,SKILL_KITS[character].w.cooldown);assert.equal(s.player.cooldowns.buff,12);tick(s,{skill:true,buff:true},1);assert.equal(s.stats.skills,1);assert.equal(s.stats.buffs,1);}});
test('walking is frame-rate independent and bounded',()=>{const a=duel(),b=duel();for(let i=0;i<60;i++)step(a,{right:true},1/60);for(let i=0;i<30;i++)step(b,{right:true},1/30);assert.ok(Math.abs(a.player.x-b.player.x)<.01);tick(a,{right:true,down:true},20);assert.ok(a.player.x<=1204&&a.player.y<=624);});
test('dodge avoids active damage and has a cooldown',()=>{const s=duel();s.player.invuln=0;s.hazards=[{type:'circle',x:700,y:500,radius:300,radiusY:200,active:true,life:1,damage:30,kind:'fire'}];step(s,{dodge:true},1/60);assert.equal(s.player.hp,280);assert.equal(s.stats.dodges,1);step(s,{dodge:true},1/60);assert.equal(s.stats.dodges,1);assert.ok(s.player.cooldowns.dodge>1);});
test('damage invulnerability prevents one-frame stacked hazard deaths',()=>{const s=duel();s.player.invuln=0;s.hazards=Array.from({length:12},()=>({type:'circle',x:700,y:500,radius:300,radiusY:200,active:true,life:1,damage:30}));step(s,{},1/60);assert.equal(s.player.hp,250);});
test('spotlight increases attack damage and energy refill',()=>{const a=duel(),b=duel();a.spotlight.x=a.player.x;a.spotlight.y=a.player.y;b.spotlight.x=100;b.spotlight.y=400;a.player.energy=b.player.energy=0;step(a,{attack:true});step(b,{attack:true});assert.ok(a.boss.hp<b.boss.hp);assert.ok(a.player.energy>b.player.energy);assert.equal(a.player.buff,true);});
test('safe-zone hazards protect inside and hit outside',()=>{const h={type:'safezone',safeX:500,safeY:480,safeRadius:110,safeRadiusY:60};assert.equal(isInsideHazard(500,480,h),false);assert.equal(isInsideHazard(620,480,h),true);assert.equal(isInsideHazard(500,550,h),true);});
test('boss order, stages and recovery are explicit and reset transient attacks',()=>{assert.deepEqual(BOSSES.map(b=>b.id),['ignis','mime','gojo','sukuna']);const s=duel(0);s.player.hp=80;s.boss.hp=1;step(s,{attack:true});assert.equal(s.status,'stageclear');assert.equal(s.stats.stagesCleared,1);startStage(s,1);assert.equal(s.player.hp,180);assert.equal(s.boss.id,'mime');assert.equal(s.status,'playing');assert.equal(s.hazards.length,0);startStage(s,1,{retry:true});assert.equal(s.player.hp,280);assert.equal(s.player.hype,0);});

test('last boss produces victory and defeat is retryable',()=>{const s=duel(BOSSES.length-1);s.boss.hp=1;step(s,{attack:true});assert.equal(s.status,'victory');const f=duel();f.player.invuln=0;f.player.hp=1;f.hazards=[{type:'circle',x:700,y:500,radius:200,radiusY:200,active:true,life:1,damage:30}];step(f);assert.equal(f.status,'gameover');startStage(f,0,{retry:true});assert.equal(f.status,'playing');assert.equal(f.player.hp,280);});
test('landing a boss finishing blow clears same-frame lingering danger',()=>{const s=duel();s.boss.hp=1;s.player.hp=1;s.player.invuln=0;s.hazards=[{type:'circle',x:700,y:500,radius:200,radiusY:150,active:true,life:1,damage:30}];step(s,{attack:true});assert.equal(s.status,'stageclear');assert.equal(s.player.hp,1);});
test('ordinary hit stun does not desynchronize cast warning from its ground hazard',()=>{const s=duel();s.boss.stun=1;s.boss.telegraph={remaining:.5,duration:.5,index:0,aim:{x:700,y:500}};s.hazards=[{type:'circle',x:700,y:500,radius:60,radiusY:40,active:false,remaining:.5,duration:.5,life:1,damage:20}];step(s,{},1/30);assert.ok(Math.abs(s.boss.telegraph.remaining-s.hazards[0].remaining)<.001);});
test('R requires full hype, freezes for its cinematic and only then begins actual strikes',()=>{const s=duel();step(s,{ultimate:true});assert.equal(s.stats.ultimates,0);s.player.hype=100;s.hazards=[{type:'circle',x:700,y:500,radius:50,remaining:1,life:1,active:false}];const hp=s.boss.hp;step(s,{ultimate:true});assert.equal(s.stats.ultimates,1);assert.equal(s.cinematic.kind,'playerUltimate');assert.equal(s.boss.hp,hp);assert.equal(s.player.cooldowns.ultimate,42);const x=s.player.x;tick(s,{right:true,ultimate:true},.5);assert.equal(s.player.x,x);assert.equal(s.boss.hp,hp);finishCut(s);assert.equal(s.cinematic,null);assert.ok(s.boss.hp<hp);assert.equal(s.player.attackSequence.hitIndex,1);assert.equal(s.stats.ultimates,1);});

test('all bosses telegraph and every long simulation remains finite',()=>{for(let stage=0;stage<BOSSES.length;stage++){const s=createGame({stage,skipIntro:true});let sawTelegraph=false;for(let i=0;i<2400&&s.status==='playing';i++){step(s,{left:i%360<180,right:i%360>=180,dodge:i%100===0},1/30);sawTelegraph||=!!s.boss.telegraph;for(const n of [s.player.hp,s.player.x,s.player.y,s.boss.hp,s.boss.x,s.boss.y])assert.ok(Number.isFinite(n));}assert.ok(sawTelegraph);}});

test('booth fixes ranked seed/difficulty and enforces the active-time ceiling',()=>{const s=createGame({mode:'booth',duration:60,seed:987,difficulty:'hard'});assert.equal(s.seed,424242);assert.equal(s.difficulty,'standard');s.boss.patternCooldown=1000;s.hitStop=3;for(let i=0;i<3700;i++)step(s,{},1/60);assert.equal(s.status,'finished');assert.equal(s.endReason,'timeout');assert.equal(s.runTime,60);assert.equal(s.timeLeft,0);assert.ok(s.time<58);});
test('hit stop freezes the world but counts booth time and preserves discrete inputs',()=>{const s=createGame({mode:'booth'});s.player.x=700;s.boss.x=780;s.boss.patternCooldown=99;s.hitStop=.08;const x=s.player.x;step(s,{right:true,skill:true},1/30);assert.equal(s.player.x,x);assert.equal(s.stats.skills,0);assert.ok(s.runTime>0);assert.equal(s.inputBuffer.skill,true);tick(s,{},.15);assert.equal(s.stats.skills,1);assert.ok(s.player.cooldowns.skill>0);});
test('booth boss kills advance automatically without a stageclear modal',()=>{const s=createGame({mode:'booth'});s.player.x=700;s.boss.x=780;s.boss.y=s.player.y;s.boss.hp=1;step(s,{attack:true});assert.equal(s.status,'playing');assert.ok(s.transitionTimer>0);assert.equal(s.stats.stagesCleared,1);tick(s,{},1);assert.equal(s.stage,1);assert.equal(s.round,1);assert.equal(s.status,'playing');assert.equal(s.stats.stagesCleared,1);});
test('booth cycles its two bosses into a modestly stronger encore',()=>{const s=createGame({mode:'booth'}),base=s.boss.maxHp;for(let i=0;i<BOSSES.length;i++){s.boss.hp=0;step(s);tick(s,{},.94);finishCut(s);}assert.equal(s.round,BOSSES.length);assert.equal(s.stage,0);assert.equal(s.stats.stagesCleared,BOSSES.length);assert.equal(s.boss.maxHp,Math.round(base*1.15));});
test('score counts actual HP removed, with no overkill or duplicate kill inflation',()=>{const s=createGame({mode:'booth'});s.player.x=700;s.boss.x=780;s.boss.y=500;s.boss.hp=7;s.spotlight.x=100;step(s,{attack:true});assert.equal(s.stats.damageDealt,7);assert.equal(s.score,7);assert.equal(s.stats.bossKills,1);tick(s,{},.1);assert.equal(s.score,7);});
test('four consecutive attacks create a launching finisher and reset after a gap',()=>{const s=duel();let landed=false;for(let i=0;i<180&&!landed;i++){step(s,{attack:true},1/60);landed=s.stats.finishers>0;}assert.ok(landed);assert.equal(s.player.comboIndex,4);assert.ok(s.boss.launchV>0);assert.ok(Math.abs(s.boss.knockX)>0);assert.ok(s.effects.some(e=>e.type==='impact'&&e.comboIndex===4));tick(s,{},1.1);step(s,{attack:true});assert.equal(s.player.comboIndex,1);});
test('held normal attacks do not permanently stagger or cancel boss casts',()=>{const s=duel();s.boss.patternCooldown=.3;tick(s,{attack:true},2);assert.ok(s.boss.attacks>=1);assert.ok(s.boss.telegraph||s.hazards.length||s.projectiles.length);});
test('precise last-window press queues a JUST hit even after key release',()=>{const s=duel();step(s,{attack:true});while(s.player.attackCooldown>.13)step(s,{},1/60);step(s,{attackPressed:true},1/60);while(s.hitStop>0)step(s);step(s);assert.ok(s.player.precisionQueued);for(let i=0;i<30&&s.stats.justHits===0;i++)step(s,{},1/60);assert.equal(s.stats.justHits,1);assert.equal(s.score,s.stats.damageDealt+60);assert.equal(s.player.timingGrade,'JUST HIT');});
test('early repeated attack spam cannot upgrade the same recovery into JUST',()=>{const s=duel();step(s,{attack:true});tick(s,{attackPressed:true},1.2);assert.equal(s.stats.justHits,0);assert.ok(s.stats.hits>=3);});
test('JUST dodge rewards only its first .115 seconds and once per dodge',()=>{const s=duel();s.player.invuln=0;s.hazards=[{type:'circle',x:700,y:500,radius:500,radiusY:300,active:true,life:1,damage:20}];step(s,{dodge:true});tick(s,{},.12);assert.equal(s.stats.justDodges,1);assert.equal(s.score,150);const late=duel();late.player.invuln=0;step(late,{dodge:true});tick(late,{},.14);late.hazards=[{type:'circle',x:late.player.x,y:late.player.y,radius:200,radiusY:150,active:true,life:1,damage:20}];step(late);assert.equal(late.stats.justDodges,0);assert.equal(late.player.hp,280);});
test('director W interrupts only the final .30 seconds of a nearby cast',()=>{for(const [remaining,interrupts] of [[.25,true],[.65,false]]){const s=duel();s.boss.telegraph={name:'테스트',remaining,duration:1,index:0,attackId:991,aim:{x:700,y:500}};s.hazards=[{type:'circle',attackId:991,x:700,y:500,radius:60,radiusY:40,active:false,remaining,duration:1,life:.5,damage:20}];step(s,{skill:true});assert.equal(s.boss.telegraph===null,interrupts);if(interrupts)assert.equal(s.player.timingGrade,'CUT!');}});

function fatalDomain(s,extra={}){const h={name:s.boss.patterns[3],type:'safezone',kind:'domain',attackId:999,x:640,y:480,radius:1000,radiusY:500,safeX:300,safeY:480,safeRadius:100,safeRadiusY:60,active:true,remaining:0,duration:1.85,life:2.6,damage:30,color:s.boss.color,...extra};s.hazards=[h];return h;}
test('v14 has four original named bosses and keeps only compatibility IDs for later acts',()=>{assert.deepEqual(BOSSES.map(b=>b.id),['ignis','mime','gojo','sukuna']);assert.deepEqual(BOSSES.map(b=>b.name),['이그니스','미메','프리즘','카덴']);assert.equal(createGame({stage:99}).boss.id,'sukuna');assert.equal(createGame({stage:-3}).boss.id,'ignis');assert.equal(createGame().version,14);for(const b of BOSSES){assert.equal(b.patterns.length,5);assert.ok(!/고죠|스쿠나|죠고|마히토|술식|영역전개|무라사키|무량공처|복마어주자/.test(JSON.stringify({...b,id:undefined})));}});

test('story finishes after all four original bosses with manual stage breaks',()=>{const s=duel(0);for(let stage=0;stage<BOSSES.length;stage++){if(stage){startStage(s,stage);finishCut(s);}s.player.x=700;s.boss.x=780;s.boss.y=s.player.y;s.boss.hp=1;step(s,{attack:true});assert.equal(s.status,stage===BOSSES.length-1?'victory':'stageclear');assert.equal(s.stats.stagesCleared,stage+1);}});

test('active domains kill full HP through every invulnerability, guard and action',()=>{for(const input of [{},{skill:true},{role:true},{dodge:true},{ultimate:true}]){const s=duel();s.player.hp=s.player.maxHp;s.player.invuln=100;s.player.hype=100;fatalDomain(s);step(s,input);assert.equal(s.player.hp,0);assert.equal(s.status,'gameover');assert.equal(s.endReason,'domain');assert.equal(s.domainDeath.bossId,'gojo');assert.ok(s.effects.some(e=>e.type==='domaincut'&&e.fatal));}});
test('hit stop cannot protect an already exposed player from an active domain',()=>{const s=duel();s.hitStop=10;fatalDomain(s);step(s,{ultimate:true});assert.equal(s.endReason,'domain');assert.equal(s.player.hp,0);});
test('inside the actual safe ellipse survives; its outside edge is lethal',()=>{for(const [offset,survives] of [[99.9,true],[100.1,false]]){const s=duel();fatalDomain(s);s.player.x=300+offset;s.player.y=480;s.player.invuln=0;step(s);assert.equal(s.player.hp>0,survives);}const s=duel();fatalDomain(s,{safeX:s.player.x,safeY:s.player.y});tick(s,{},.5);assert.equal(s.player.hp,280);});
test('domain warning is nonlethal, but the very first active collision kills',()=>{const s=duel();fatalDomain(s,{active:false,remaining:.2});tick(s,{},.1);assert.equal(s.player.hp,280);tick(s,{},.2);assert.equal(s.endReason,'domain');const first=duel();fatalDomain(first,{active:false,remaining:.001});step(first);assert.equal(first.endReason,'domain');});
test('R cancels an uncommitted takeover warning but cannot erase an active field',()=>{const warning=duel();warning.player.hype=100;fatalDomain(warning,{active:false,remaining:1.7});step(warning,{ultimate:true});assert.equal(warning.cinematic.kind,'playerUltimate');finishCut(warning);assert.equal(warning.hazards.length,0);assert.equal(warning.status,'playing');const active=duel();active.player.hype=100;fatalDomain(active,{safeX:active.player.x,safeY:active.player.y});step(active,{ultimate:true});tick(active,{},.9);assert.equal(active.hazards.length,1);assert.equal(active.status,'playing');finishCut(active);active.player.x=300;step(active);assert.equal(active.endReason,'domain');});
test('precise W CUT cancels a domain warning; E protection cannot erase an active field',()=>{const warning=duel();warning.boss.telegraph={remaining:.25,duration:1.85,index:3,attackId:999,aim:{x:700,y:500}};fatalDomain(warning,{active:false,remaining:.25});step(warning,{skill:true});assert.equal(warning.hazards.length,0);assert.equal(warning.player.timingGrade,'CUT!');const active=duel();fatalDomain(active,{safeX:active.player.x,safeY:active.player.y});step(active,{buff:true});assert.equal(active.hazards.length,1);});
test('fatal domain owns its safe window, with no overlapping next boss cast',()=>{const s=duel();s.boss.patternCooldown=0;fatalDomain(s,{safeX:s.player.x,safeY:s.player.y});tick(s,{},1);assert.equal(s.boss.attacks,0);assert.equal(s.player.hp,280);});
test('both bosses retain at least 1.65 seconds of domain warning on hard phase two',()=>{for(let stage=0;stage<BOSSES.length;stage++){const s=createGame({stage,difficulty:'hard',skipIntro:true});s.boss.phase=2;s.boss.patternIndex=3;s.boss.patternCooldown=0;step(s);assert.ok(s.boss.telegraph.duration>=1.65);assert.ok(s.hazards[0].duration>=1.65);assert.equal(s.hazards[0].safeRadius,s.spotlight.radius);assert.equal(s.hazards[0].safeRadiusY,s.spotlight.radiusY);}});

test('both fixed kits export usable Q W E R names, descriptions and cooldowns',()=>{for(const character of ['director','actor'])for(const key of ['q','w','e','r']){const skill=SKILL_KITS[character][key];assert.ok(skill.name.length>1);assert.ok(skill.description.length>5);assert.ok(skill.cooldown>0);}assert.equal(SKILL_KITS.director.r.name,'원 테이크 — 전원 액션!');assert.equal(SKILL_KITS.actor.r.name,'천의 얼굴 — 커튼콜');});
test('actor W temporarily casts a bow and automatically returns to sword',()=>{const s=duel(0,'actor');s.player.x=300;s.boss.x=1100;step(s,{skill:true,role:true});assert.equal(s.player.character,'actor');assert.equal(s.player.role,'sword');assert.equal(s.player.castRole,'bow');assert.equal(s.projectiles.filter(q=>q.kind==='star-arrow').length,5);tick(s,{},.8);assert.equal(s.player.castRole,'sword');assert.equal(s.player.character,'actor');});
test('actor Q stays a melee sword combo and cannot become a persistent bow',()=>{const s=duel(0,'actor');step(s,{attack:true,role:true,swap:true});assert.equal(s.player.role,'sword');assert.equal(s.player.attackKind,'sword');assert.equal(s.projectiles.length,0);assert.ok(s.boss.hp<s.boss.maxHp);});
test('director E grants five-second damage and movement buffs plus one ordinary block',()=>{const a=duel(),b=duel();step(a,{buff:true});assert.equal(a.player.buffTimer,5);assert.equal(a.player.buffName,SKILL_KITS.director.e.name);step(a,{attack:true});step(b,{attack:true});assert.ok(a.stats.damageDealt>b.stats.damageDealt);const guard=duel();step(guard,{buff:true});guard.player.invuln=0;guard.hazards=[{type:'circle',x:700,y:500,radius:600,radiusY:400,active:true,life:2,damage:30}];step(guard);assert.equal(guard.player.hp,280);assert.equal(guard.stats.blocks,1);assert.equal(guard.player.shieldCharges,0);tick(guard,{},.3);assert.ok(guard.player.hp<280);});
test('actor E accelerates attacks and movement, expires, and has no block charge',()=>{const a=duel(0,'actor'),b=duel(0,'actor');step(a,{buff:true});step(a,{attack:true});step(b,{attack:true});assert.ok(a.player.attackCooldown<b.player.attackCooldown);assert.ok(a.stats.damageDealt>b.stats.damageDealt);assert.equal(a.player.shieldCharges,0);const move=createGame({character:'actor',skipIntro:true});move.boss.patternCooldown=99;step(move,{buff:true});const x=move.player.x;tick(move,{right:true},.2);assert.ok(move.player.x-x>60);tick(move,{},5.1);assert.equal(move.player.buffTimer,0);assert.equal(move.player.buffName,'');});
test('E single-hit protection never blocks a fatal domain',()=>{const s=duel();step(s,{buff:true});assert.equal(s.player.shieldCharges,1);fatalDomain(s);step(s);assert.equal(s.player.hp,0);assert.equal(s.endReason,'domain');});
test('each R sequence belongs to the fixed single character',()=>{for(const character of ['director','actor']){const s=duel(0,character);s.player.hype=100;step(s,{ultimate:true});finishCut(s);const cuts=s.effects.filter(e=>e.type==='skillcut');tick(s,{},2.6);assert.equal(s.cinematic,null);assert.ok(s.boss.hp<s.boss.maxHp-600);assert.ok(cuts.some(e=>e.character===character&&e.text===SKILL_KITS[character].r.name));assert.ok(!cuts.some(e=>e.character==='duo'));assert.equal(s.player.character,character);assert.ok(s.effects.some(e=>e.type==='impact'&&e.kind==='ultimate'));}});
test('boss cinematics freeze all hazards, position, HP and world time while run time advances',()=>{const s=duel();s.boss.patternIndex=3;s.boss.patternCooldown=0;step(s);assert.equal(s.cinematic.kind,'domain');const snapshot={x:s.player.x,y:s.player.y,hp:s.player.hp,time:s.time,warning:s.hazards[0].remaining,runTime:s.runTime};s.projectiles.push({id:999,owner:'enemy',kind:'test',x:s.player.x,y:s.player.y,vx:0,vy:0,radius:100,radiusY:100,damage:999,life:1});tick(s,{right:true,skill:true,buff:true,attack:true,ultimate:true,dodge:true},.3);assert.equal(s.player.x,snapshot.x);assert.equal(s.player.y,snapshot.y);assert.equal(s.player.hp,snapshot.hp);assert.equal(s.time,snapshot.time);assert.equal(s.hazards[0].remaining,snapshot.warning);assert.ok(s.runTime>snapshot.runTime+.29);assert.equal(s.stats.skills,0);assert.equal(s.stats.buffs,0);assert.deepEqual(s.inputBuffer,{});});
test('cinematic ends with full warning intact and no buffered automatic skill',()=>{const s=duel();s.boss.patternIndex=3;s.boss.patternCooldown=0;step(s);const warning=s.boss.telegraph.duration;while(s.cinematic)step(s,{skill:true,buff:true,attackPressed:true},1/60);assert.equal(s.boss.telegraph.remaining,warning);assert.equal(s.hazards[0].remaining,warning);assert.equal(s.stats.skills,0);assert.equal(s.stats.buffs,0);step(s,{},1/60);assert.equal(s.stats.skills,0);assert.equal(s.stats.buffs,0);assert.equal(s.player.queuedAttack,false);assert.ok(s.boss.telegraph.remaining<warning);});
