test('Gojo creates distance and a flank while Sukuna pressures closer at the same 72 speed',()=>{for(const stage of [bossIndex('gojo'),bossIndex('sukuna')]){const s=duel(stage);s.boss.x=s.player.x+130;s.boss.y=s.player.y;s.boss.patternCooldown=99;const x=s.boss.x,y=s.boss.y,rng=s.rng;step(s,{},1/30);assert.ok(s.boss.id==='gojo'?s.boss.x>x:s.boss.x<x);assert.ok(s.boss.y>y);assert.ok(Math.abs(Math.hypot(s.boss.x-x,s.boss.y-y)-72/30)<1e-9);assert.equal(s.rng,rng);}});
