function purpleDuel({difficulty='standard',phase=1,character='director'}={}){const s=createGame({stage:bossIndex('gojo'),skipIntro:true,difficulty,character});s.player.x=520;s.player.y=500;s.boss.x=950;s.boss.y=480;s.boss.phase=phase;s.boss.patternIndex=2;s.boss.patternCooldown=0;step(s);return s;}
test('Purple tracks the actual player early then locks its visible lane for the final half-second',()=>{const s=purpleDuel(),h=s.hazards[0],initial=h.angle;for(let i=0;i<12;i++)step(s,{up:true});assert.ok(h.tracking);assert.notEqual(h.angle,initial);assert.equal(h.x,(s.boss.x+s.player.x)/2);assert.equal(h.y,(s.boss.y+s.player.y)/2);assert.equal(h.angle,Math.atan2(s.player.y-s.boss.y,s.player.x-s.boss.x));assert.equal(s.cinematic,null);let lastTrackingRemaining=h.remaining;while(h.tracking){lastTrackingRemaining=h.remaining;step(s);}assert.ok(lastTrackingRemaining>=.5-1e-9);assert.ok(h.remaining>=.5-1/60-1e-9);assert.equal(h.locked,true);const geometry=[h.x,h.y,h.angle],aim={...s.boss.telegraph.aim};for(let i=0;i<20;i++)step(s,{down:true});assert.deepEqual([h.x,h.y,h.angle],geometry);assert.deepEqual(s.boss.telegraph.aim,aim);assert.equal(s.boss.telegraph.tracking,false);assert.equal(s.boss.telegraph.locked,true);});
test('the emitted Purple beam and active collider keep the exact locked warning geometry',()=>{const s=purpleDuel(),h=s.hazards[0];while(h.tracking)step(s);const geometry={x:h.x,y:h.y,width:h.width,height:h.height,angle:h.angle};while(!h.active)step(s);const beam=s.effects.find(e=>e.type==='beam');for(const key of Object.keys(geometry))assert.equal(beam[key],geometry[key]);assert.equal(h.tracking,false);assert.equal(h.locked,true);assert.ok(s.stats.damageTaken>0);});
test('ordinary directional movement after Purple locks avoids it on every difficulty and phase',()=>{for(const difficulty of ['rehearsal','standard','hard'])for(const phase of [1,2])for(const character of ['director','actor']){const s=purpleDuel({difficulty,phase,character}),h=s.hazards[0];while(h.tracking)step(s);tick(s,{},.1);while(h.life>0&&s.status==='playing')step(s,{up:true});assert.equal(s.stats.damageTaken,0,`${difficulty}/${phase}/${character}`);assert.equal(s.player.hp,s.player.maxHp);assert.equal(s.stats.dodges,0);}});
test('only Purple becomes wider and faster; boss damage and other warning durations remain unchanged',()=>{for(const phase of [1,2]){const s=purpleDuel({phase}),h=s.hazards[0];assert.equal(h.height,phase===2?118:106);assert.ok(Math.abs(h.duration-1.25*(phase===2?.94:1))<1e-9);assert.equal(h.width,1500);assert.equal(h.damage,38*1.7);assert.equal(h.lockWindow,.5);}for(const [stage,index,warning] of [[bossIndex('gojo'),0,1.05],[bossIndex('gojo'),1,1],[bossIndex('sukuna'),0,1],[bossIndex('sukuna'),1,1],[bossIndex('sukuna'),2,1.3]]){const s=duel(stage);s.boss.patternIndex=index;s.boss.patternCooldown=0;step(s);assert.equal(s.hazards[0].duration,warning);}});
test('postcast recovery is ten percent shorter with all difficulty and boss factors retained',()=>{for(const stage of [bossIndex('gojo'),bossIndex('sukuna')])for(const phase of [1,2])for(const difficulty of ['rehearsal','standard','hard']){const s=createGame({stage,skipIntro:true,difficulty});s.boss.phase=phase;s.boss.telegraph={remaining:.001,duration:1,index:0,aim:{x:700,y:500}};step(s);const modifier={rehearsal:1.12,standard:1,hard:.88}[difficulty],expected=(phase===2?.765:1.08)*modifier*(s.boss.id==='sukuna'?.85:1);assert.ok(Math.abs(s.boss.patternCooldown-expected)<1e-9);}});

test('hard phase-two domain safety remains reachable by walking from every arena corner',()=>{for(const stage of BOSSES.map((_,i)=>i))for(const x of [76,640,1204])for(const y of [340,480,624]){const s=createGame({stage,difficulty:'hard',skipIntro:true});s.player.x=x;s.player.y=y;s.boss.phase=2;s.boss.patternIndex=3;s.boss.patternCooldown=0;step(s);while(s.cinematic)step(s);const h=s.hazards[0];for(let i=0;i<220&&!h.active&&s.status==='playing';i++){const dx=h.safeX-s.player.x,dy=h.safeY-s.player.y;step(s,{left:dx<-5,right:dx>5,up:dy<-5,down:dy>5});}assert.equal(h.active,true);assert.equal(s.status,'playing',`${stage}/${x}/${y}`);assert.equal(isInsideHazard(s.player.x,s.player.y,h),false);assert.equal(s.player.hp,s.player.maxHp);assert.equal(s.stats.dodges,0);}});

