test('challenge keeps fatal final-boss domains and clears all danger on victory',()=>{const s=createGame({mode:'challenge'});startStage(s,BOSSES.length-1);finishCut(s);s.player.invuln=999;fatalDomain(s);step(s);assert.equal(s.endReason,'domain');assert.equal(s.status,'gameover');const clear=createGame({mode:'challenge'});startStage(clear,BOSSES.length-1);finishCut(clear);fatalDomain(clear,{safeX:clear.player.x,safeY:clear.player.y});clear.player.hype=100;clear.boss.hp=1;step(clear,{ultimate:true});finishCut(clear);step(clear);assert.equal(clear.status,'victory');assert.equal(clear.endReason,'clear');assert.equal(clear.hazards.length,0);assert.equal(clear.projectiles.length,0);assert.ok(clear.player.hp>0);});

test('later normal boss attacks match the pre-v8 snapshot across every phase and difficulty',()=>{
 const rows=[];
 for(const id of ['gojo','sukuna'])for(const difficulty of ['rehearsal','standard','hard'])for(const phase of [1,2])for(let index=0;index<3;index++){
  const s=createGame({stage:bossIndex(id),difficulty,skipIntro:true});s.player.x=520;s.player.y=500;s.boss.x=950;s.boss.y=480;s.boss.phase=phase;s.boss.patternIndex=index;s.boss.patternCooldown=0;step(s);
  const keys=['type','kind','x','y','radius','radiusY','width','height','angle','duration','life','damage','safeX','safeY','safeRadius','safeRadiusY','tracking','locked','lockWindow'];
  rows.push({id,difficulty,phase,index,maxHp:s.boss.maxHp,damage:s.boss.damage,warning:s.boss.telegraph.duration,cinematic:s.cinematic?.duration,hazards:s.hazards.map(h=>Object.fromEntries(keys.map(k=>[k,h[k]])))});
 }
 assert.equal(createHash('sha256').update(JSON.stringify(rows)).digest('hex'),'59092be1eae68f6b4015039f6931824b54b7572248b7030e492fa8f2f812f105');
});
function openingPattern(id,index,character='director'){
 const s=createGame({stage:bossIndex(id),skipIntro:true,character});s.player.x=520;s.player.y=500;s.boss.x=950;s.boss.y=480;s.boss.patternIndex=index;s.boss.patternCooldown=0;s.player.invuln=0;step(s);return s;
}
test('opening bosses have three distinct normal attacks and a generous signature safe zone',()=>{
 for(const [id,kinds,radius] of [['ignis',['footlight','light-sweep','spark-spot'],145],['mime',['ribbon-thrust','mask-slam','ribbon-cross'],135]]){
  for(let index=0;index<3;index++){const s=openingPattern(id,index);assert.ok(s.hazards.some(h=>h.kind===kinds[index]));assert.equal(s.cinematic,null);assert.ok(s.hazards.every(h=>h.duration>=1.35));assert.ok(s.hazards.every(h=>h.totalLife===h.life));}
  const s=openingPattern(id,3);assert.equal(s.cinematic.kind,'domain');assert.ok(s.hazards[0].duration>=2.25);assert.equal(s.hazards[0].safeRadius,radius);
 }
});
test('each new normal attack deals real damage if ignored and is avoidable by directional walking',()=>{
 for(const id of ['ignis','mime'])for(let index=0;index<3;index++)for(const character of ['director','actor']){
  const ignored=openingPattern(id,index,character),escaped=openingPattern(id,index,character);
  for(let f=0;f<180&&ignored.hazards.length;f++)step(ignored);
  assert.ok(ignored.stats.damageTaken>0,`${id}/${index}: ignored warning must hurt`);
  // Delayed response, then walk perpendicular to the warning; no dodge or invulnerability.
  tick(escaped,{},.35);for(let f=0;f<180&&escaped.hazards.length;f++)step(escaped,{up:true});
  assert.equal(escaped.stats.damageTaken,0,`${id}/${index}/${character}: readable escape`);assert.equal(escaped.stats.dodges,0);
 }
});
test('Mime fake mask never collides, deals damage or grants a dodge score',()=>{
 const s=openingPattern('mime',1),fake=s.hazards.find(h=>h.decoy),real=s.hazards.find(h=>h.kind==='mask-slam');assert.ok(fake&&real);assert.equal(fake.damage,0);assert.equal(fake.cue,'FAKE');assert.equal(real.cue,'HIT');assert.equal(isInsideHazard(fake.x,fake.y,fake),false);
 s.player.x=fake.x;s.player.y=fake.y;while(!fake.active)step(s);step(s,{dodge:true});tick(s,{},.3);assert.equal(s.stats.damageTaken,0);assert.equal(s.stats.justDodges,0);assert.equal(s.score,0);
});
test('opening bosses do not overlap separate attack windows or shorten the first teaching sequence',()=>{
 for(const id of ['ignis','mime']){const s=createGame({mode:'challenge'});startStage(s,bossIndex(id),{retry:true});s.boss.patternCooldown=0;step(s);assert.equal(s.boss.telegraph.index,0);const attackId=s.hazards[0].attackId;
  for(let f=0;f<300&&s.hazards.some(h=>h.attackId===attackId);f++){step(s,{up:true});assert.equal(s.boss.attacks,1);}
  assert.equal(s.hazards.length,0);assert.ok(s.boss.patternCooldown>1);assert.equal(s.boss.patternIndex,1);
 }
});
test('all four signatures have an actually reachable walking route through every phase',()=>{for(const id of BOSSES.map(b=>b.id))for(const character of ['director','actor']){const s=openingPattern(id,3,character);finishCut(s);for(let i=0;i<2400&&s.hazards.length&&s.status==='playing';i++){const h=s.hazards[0],g=getDomainGuide(s,h),dx=g.target.x-s.player.x,dy=g.target.y-s.player.y;step(s,{left:dx<-4,right:dx>4,up:dy<-4,down:dy>4});}assert.equal(s.status,'playing',id+'/'+character);assert.equal(s.player.hp,280);assert.equal(s.hazards.length,0);}});

test('R emits actual damage metadata only on its committed strike frames',()=>{for(const character of ['director','actor']){const s=duel(0,character);s.player.hype=100;s.boss.hp=111;step(s,{ultimate:true});assert.equal(s.effects.filter(e=>e.type==='impact').length,0);finishCut(s);const first=s.effects.find(e=>e.type==='impact');assert.equal(first.targetId,'ignis');assert.equal(first.attackId,s.player.attackId);assert.equal(first.hitIndex,1);assert.equal(first.hitCount,12);assert.equal(first.finisher,false);assert.equal(first.time,s.time);assert.ok(first.damage>0);assert.equal(s.stats.ultimates,1);}});

test('each boss review is one presentation event and never adds score',()=>{
 const s=createGame({mode:'challenge'});s.boss.hp=0;step(s);const reviews=s.effects.filter(e=>e.type==='comic'&&e.subtitle?.includes('심사 종료'));assert.equal(reviews.length,1);assert.equal(reviews[0].text,BOSSES[0].review);tick(s,{},.1);assert.equal(s.effects.filter(e=>e.type==='comic').length,1);assert.equal(s.score,0);
});

function collectImpacts(s,input,seconds){const hits=new Map();for(let f=0;f<seconds*60;f++){step(s,typeof input==='function'?input(s,f):input);for(const e of s.effects)if(e.type==='impact')hits.set(e.id,e);}return [...hits.values()];}
test('one released Q press commits exactly three separated strikes for each fixed kit',()=>{for(const character of ['director','actor']){const s=duel(0,character);step(s,{attackPressed:true});const first=s.effects.find(e=>e.type==='impact');assert.ok(first);assert.equal(first.hitIndex,1);const hits=[first,...collectImpacts(s,{},.6)].filter((e,i,a)=>a.findIndex(x=>x.id===e.id)===i);assert.equal(hits.length,3);assert.deepEqual(hits.map(e=>e.hitIndex),[1,2,3]);assert.ok(hits.every(e=>e.hitCount===3&&e.attackId===first.attackId));assert.ok(hits[1].time-hits[0].time>=.09);assert.ok(hits[2].time-hits[1].time>=.09);assert.equal(s.stats.hits,3);assert.equal(s.player.attackSequence,null);}});
test('the fourth Q action has three hits and a single strong launching final strike',()=>{for(const character of ['director','actor']){const s=duel(0,character);s.player.comboIndex=3;s.player.chainTimer=.9;step(s,{attackPressed:true});const first=s.effects.find(e=>e.type==='impact'),hits=[first,...collectImpacts(s,{},.5)].filter((e,i,a)=>a.findIndex(x=>x.id===e.id)===i);assert.equal(hits.length,3);assert.deepEqual(hits.map(e=>e.finisher),[false,false,true]);assert.equal(hits[2].kind,'finisher');assert.ok(hits[2].damage>hits[0].damage*2);assert.equal(s.stats.finishers,1);assert.ok(s.boss.launchZ>0);}});
test('Space takes priority over Q W R and immediately cancels uncommitted Q strikes',()=>{const s=duel();step(s,{attackPressed:true});const before=s.stats.hits;step(s,{attack:true,attackPressed:true,skill:true,ultimate:true,dodge:true});assert.ok(s.player.dodgeTimer>0);assert.equal(s.player.attackSequence,null);tick(s,{},.3);assert.equal(s.stats.hits,before);assert.equal(s.stats.skills,0);assert.equal(s.stats.ultimates,0);});
test('R makes twelve real strikes and one finisher, with its advertised base total',()=>{for(const character of ['director','actor']){const s=duel(1,character);s.spotlight.x=50;s.spotlight.y=340;s.player.hype=100;s.boss.hp=s.boss.maxHp=10000;step(s,{ultimate:true});finishCut(s);const first=s.effects.find(e=>e.type==='impact'),start=s.runTime;const hits=[first,...collectImpacts(s,{},2.8)].filter((e,i,a)=>a.findIndex(x=>x.id===e.id)===i);assert.equal(hits.length,12);assert.equal(hits.filter(e=>e.finisher).length,1);assert.equal(hits.at(-1).hitIndex,12);assert.ok(hits.at(-1).damage>hits[0].damage*7);assert.ok(Math.abs(s.stats.damageDealt-(character==='director'?1600:1750))<10);assert.equal(s.player.attackSequence,null);assert.ok(s.runTime-start>=2.4);assert.equal(s.stats.ultimates,1);}});
test('R cinematic discards repeated actions and freezes incoming ordinary damage',()=>{const s=duel();s.player.hype=100;step(s,{ultimate:true});s.hazards.push({type:'circle',x:s.player.x,y:s.player.y,radius:300,radiusY:300,active:true,life:5,damage:999});const hp=s.player.hp,time=s.time;tick(s,{ultimate:true,skill:true,buff:true,attackPressed:true,right:true},1.5);assert.equal(s.player.hp,hp);assert.equal(s.time,time);assert.equal(s.stats.ultimates,1);finishCut(s);step(s);assert.equal(s.player.hp,hp);assert.equal(s.stats.skills,0);assert.equal(s.stats.buffs,0);});
test('R sequence allows movement and dodge cancellation without cooldown or hype refund',()=>{const s=duel(1);s.player.hype=100;step(s,{ultimate:true});finishCut(s);const x=s.player.x;tick(s,{left:true},.2);assert.ok(s.player.x<x);const before=s.stats.hits;step(s,{dodge:true,left:true});assert.equal(s.player.attackSequence,null);tick(s,{},.3);assert.equal(s.stats.hits,before);assert.ok(s.player.cooldowns.ultimate>40);assert.ok(s.player.hype<100);});
test('remaining R cooldown crosses stage transitions and prevents an immediate second ultimate',()=>{const s=createGame({mode:'challenge'});s.player.hype=100;s.boss.hp=1;step(s,{ultimate:true});finishCut(s);step(s);assert.ok(s.transitionTimer>0);const remaining=s.player.cooldowns.ultimate;tick(s,{},1);assert.equal(s.stage,1);assert.ok(s.player.cooldowns.ultimate>=remaining-.2);assert.equal(s.player.attackSequence,null);assert.equal(s.cinematic.kind,'bossIntro');const beforeCut=s.player.cooldowns.ultimate;finishCut(s);assert.equal(s.player.cooldowns.ultimate,beforeCut);s.player.hype=100;step(s,{ultimate:true});assert.equal(s.stats.ultimates,1);assert.equal(s.cinematic,null);assert.equal(s.boss.hp,s.boss.maxHp);});
test('neither residual Q nor R can damage the next boss after a finishing strike',()=>{for(const ultimate of [false,true]){const s=createGame({mode:'challenge'});s.player.x=720;s.boss.x=800;s.boss.y=500;s.boss.hp=1;s.player.hype=100;step(s,ultimate?{ultimate:true}:{attackPressed:true});finishCut(s);step(s);tick(s,{},1.1);assert.equal(s.stage,1);assert.equal(s.boss.hp,s.boss.maxHp);assert.equal(s.player.attackSequence,null);assert.equal(s.pendingUltimate,false);}});
test('Prism and Caden each get one automatic boss intro that freezes all combat',()=>{const s=createGame({mode:'challenge'});for(const [index,duration] of [[2,2.4],[3,2.8]]){startStage(s,index);assert.equal(s.cinematic.kind,'bossIntro');assert.equal(s.cinematic.duration,duration);assert.equal(s.cinematic.actorId,BOSSES[index].id);const time=s.time,hp=s.player.hp,x=s.player.x;tick(s,{attack:true,ultimate:true,right:true},duration-.2);assert.equal(s.time,time);assert.equal(s.player.x,x);assert.equal(s.player.hp,hp);finishCut(s);startStage(s,index);assert.equal(s.cinematic,null);}});
test('every new takeover is fatal through R ordinary invulnerability on an actual active danger frame',()=>{for(const id of BOSSES.map(b=>b.id)){const s=openingPattern(id,3);finishCut(s);const h=s.hazards[0];while(!h.active){const g=getDomainGuide(s,h);s.player.x=g.target.x;s.player.y=g.target.y;step(s);}s.player.invuln=999;s.player.hype=100;let danger;for(let x=76;x<=1204&&!danger;x+=32)for(let y=340;y<=624;y+=20)if(isInsideHazard(x,y,h)){danger={x,y};break;}if(!danger&&id==='sukuna'){for(let f=0;f<60&&!danger;f++){step(s,walkTo(s,getDomainGuide(s,h).target));for(let x=76;x<=1204&&!danger;x+=32)for(let y=340;y<=624;y+=20)if(isInsideHazard(x,y,h)){danger={x,y};break;}}}assert.ok(danger,id);s.player.x=danger.x;s.player.y=danger.y;step(s,{ultimate:true,dodge:true});assert.equal(s.endReason,'domain',id);assert.ok(s.domainDeath.instruction.length>10);}});
test('takeover geometry view is read-only and exactly matches the collision source',()=>{for(const id of BOSSES.map(b=>b.id)){const s=openingPattern(id,3),h=s.hazards[0],before=JSON.stringify(s);const view=getTakeoverView(h),guide=getDomainGuide(s,h);assert.equal(JSON.stringify(s),before);assert.deepEqual(guide.safeRegions,view.safeRegions);assert.deepEqual(guide.dangerRegions,view.dangerRegions);assert.deepEqual(guide.target,view.guide);assert.equal(isInsideHazard(s.player.x,s.player.y,h),false);assert.ok(guide.remaining>=1.65);assert.ok(view.phaseCount>=1);}});
test('moving light changes its actual safe ellipse slowly without teleporting',()=>{const s=openingPattern('ignis',3);finishCut(s);const h=s.hazards[0];s.player.x=h.safeX;s.player.y=h.safeY;while(!h.active)step(s);let last={x:h.safeX,y:h.safeY};const initial=h.safeX;for(let i=0;i<120;i++){const g=getDomainGuide(s,h);step(s,{right:g.target.x-s.player.x>4,left:g.target.x-s.player.x<-4,up:g.target.y-s.player.y<-4,down:g.target.y-s.player.y>4});assert.ok(Math.hypot(h.safeX-last.x,h.safeY-last.y)<1.3);last={x:h.safeX,y:h.safeY};}assert.ok(Math.abs(h.safeX-initial)>40);assert.equal(s.player.hp,280);assert.equal(h.safeRegions[0].x,h.safeX);});
test('Mime reveals three labelled shapes and opens a real connecting corridor before switching',()=>{const s=openingPattern('mime',3);finishCut(s);const h=s.hazards[0];s.player.x=h.safeX;s.player.y=h.safeY;while(!h.phaseWarning&&s.status==='playing')step(s);assert.equal(h.panels.length,3);assert.equal(new Set(h.panels.map(p=>p.shape)).size,3);assert.ok(h.nextSafeRegions.length);assert.equal(h.phaseDuration,2);const old=h.panels[h.safeIndex],next=h.panels[h.nextSafeIndex];assert.equal(isInsideHazard((old.x+next.x)/2,480,h),false);assert.equal(getDomainGuide(s,h).target.x,next.x);s.player.x=next.x;while(h.phaseWarning)step(s);assert.equal(h.domainPhase,1);assert.equal(isInsideHazard(old.x,480,h),true);assert.equal(isInsideHazard(next.x,480,h),false);});
test('Prism alternates horizontal and vertical corridors with a full harmless relocation warning',()=>{const s=openingPattern('gojo',3);finishCut(s);const h=s.hazards[0];s.player.x=h.safeX;s.player.y=h.safeY;while(!h.phaseWarning)step(s);assert.equal(h.domainPhase,1);assert.ok(h.safeRegions[0].height>h.safeRegions[0].width);assert.equal(h.phaseDuration,1.65);assert.equal(isInsideHazard(76,340,h),false);const left=h.phaseRemaining;step(s,{right:true});assert.ok(h.phaseRemaining<left);assert.equal(s.status,'playing');});
test('Caden fires six moving walls in five phases, with at most two actual collider layers',()=>{
 const s=openingPattern('sukuna',3);finishCut(s);const h=s.hazards[0],seen=new Set(),events=new Map();let movingFrames=0;
 for(let i=0;i<2400&&s.hazards.length&&s.status==='playing';i++){
  const g=getDomainGuide(s,h);if(h.active&&!h.phaseWarning)seen.add(h.domainPhase);
  const position=h.waves[0].normalPosition,phase=h.domainPhase;step(s,walkTo(s,g.target));
  if(h.domainPhase===phase&&h.waves[0].normalPosition!==position)movingFrames++;
  assert.ok(h.waves.filter(w=>w.started&&!w.finished).length<=2);
  assert.deepEqual(h.dangerRegions,h.phaseWarning?[]:h.waves.flatMap(w=>w.segments));
  for(const e of s.effects)if(e.type==='bladeWave')events.set(e.id,e);
 }
 assert.deepEqual([...seen],[0,1,2,3,4]);assert.equal(s.player.hp,280);assert.equal(s.hazards.length,0);assert.ok(movingFrames>600);
 const launches=[...events.values()].filter(e=>e.kind==='launch');assert.equal(launches.length,6);assert.equal(new Set(launches.map(e=>e.waveId)).size,6);
 assert.deepEqual(launches.map(e=>e.direction),['left-to-right','right-to-left','top-to-bottom','bottom-to-top','diagonal','diagonal']);
});

test('three basic hits do not triple the per-action hype reward and R cannot recharge itself',()=>{const q=duel(0);q.spotlight.x=50;q.spotlight.y=340;step(q,{attackPressed:true});tick(q,{},.35);assert.equal(q.stats.hits,3);assert.ok(q.player.hype<5);for(const character of ['director','actor']){const r=duel(1,character);r.spotlight.x=50;r.spotlight.y=340;r.player.hype=100;step(r,{ultimate:true});finishCut(r);tick(r,{},2.7);assert.ok(r.player.hype<5,character);assert.equal(r.stats.ultimates,1);}});
test('standing at the initial moving-light center eventually dies unless the player follows it',()=>{for(const character of ['director','actor']){const s=openingPattern('ignis',3,character);finishCut(s);const h=s.hazards[0];s.player.x=h.safeX;s.player.y=h.safeY;tick(s,{},8);assert.equal(s.endReason,'domain');assert.equal(s.player.hp,0);}});
test('Prism next-corridor relocation is possible from both extreme ends without a dodge',()=>{for(const character of ['director','actor'])for(const side of [-1,1]){const s=openingPattern('gojo',3,character);finishCut(s);const h=s.hazards[0];s.player.x=h.safeX;s.player.y=h.safeY;s.player.cooldowns.dodge=99;while(!h.active)step(s);let phase=0;while(phase<3&&s.status==='playing'){const r=h.safeRegions[0];if(r.width>1000){s.player.x=side<0?76:1204;s.player.y=r.y;}else{s.player.x=r.x;s.player.y=side<0?340:624;}assert.equal(isInsideHazard(s.player.x,s.player.y,h),false);assert.ok(h.nextSafeRegions.length===1);while(!h.phaseWarning&&s.status==='playing')step(s);assert.ok(h.phaseDuration>=1.65);tick(s,{},.35);while(h.phaseWarning&&s.status==='playing'){const g=getDomainGuide(s,h),dx=g.target.x-s.player.x,dy=g.target.y-s.player.y;step(s,{left:dx<-4,right:dx>4,up:dy<-4,down:dy>4});}assert.equal(s.status,'playing',character+'/'+side+'/'+phase);assert.equal(isInsideHazard(s.player.x,s.player.y,h),false);phase++;}assert.equal(phase,3);assert.equal(s.stats.dodges,0);}});
test('all takeover paths are walkable from arena corners for either kit with dodge unavailable',()=>{for(const id of BOSSES.map(b=>b.id))for(const character of ['director','actor'])for(const x of [76,1204])for(const y of [340,624]){const s=createGame({stage:bossIndex(id),character,skipIntro:true});s.player.x=x;s.player.y=y;s.player.cooldowns.dodge=99;s.boss.patternIndex=3;s.boss.patternCooldown=0;step(s);finishCut(s);let count=0;while(s.hazards.length&&s.status==='playing'&&count++<2400){const g=getDomainGuide(s,s.hazards[0]),dx=g.target.x-s.player.x,dy=g.target.y-s.player.y;step(s,{left:dx<-4,right:dx>4,up:dy<-4,down:dy>4});}assert.equal(s.status,'playing',id+'/'+character+'/'+x+'/'+y);assert.equal(s.hazards.length,0);assert.equal(s.player.hp,280);assert.equal(s.stats.dodges,0);}});

test('director earns one cue only after a completed hitting Q bundle, never per hit or whiff',()=>{const s=duel(0);step(s,{attackPressed:true});assert.equal(s.boss.cueMarks,0);tick(s,{},.14);assert.equal(s.boss.cueMarks,0);tick(s,{},.2);assert.equal(s.boss.cueMarks,1);const cancel=duel(0);step(cancel,{attackPressed:true});step(cancel,{dodge:true});tick(cancel,{},.3);assert.equal(cancel.boss.cueMarks,0);const miss=duel(0);miss.boss.x=1100;step(miss,{attackPressed:true});tick(miss,{},.5);assert.equal(miss.boss.cueMarks,0);});
test('director cue marks cap at three and W consumes them into three actual delayed explosions',()=>{const s=duel(0);s.boss.hp=s.boss.maxHp=10000;tick(s,{attack:true},2.8);assert.equal(s.boss.cueMarks,3);s.player.x=s.boss.x-85;s.player.y=s.boss.y;s.hitStop=0;step(s,{skill:true});assert.equal(s.boss.cueMarks,0);assert.equal(s.stats.cueDetonations,1);assert.equal(s.followups.filter(f=>f.source==='cue-detonation').length,3);assert.ok(!s.effects.some(e=>e.type==='impact'&&e.source==='cue-detonation'));const hits=collectImpacts(s,{},1).filter(e=>e.source==='cue-detonation');assert.equal(hits.length,3);assert.deepEqual(hits.map(e=>e.cueIndex),[1,2,3]);assert.ok(hits.every(e=>e.damage>0&&e.cueCount===3));assert.ok(hits[1].time>hits[0].time);});
test('director E grants exactly one real light-and-sound support bundle from W or Q finisher',()=>{for(const trigger of ['skill','attack']){const s=duel(0);s.boss.hp=10000;step(s,{buff:true});assert.equal(s.player.crewReady,true);if(trigger==='attack'){s.player.comboIndex=3;s.player.chainTimer=.9;}s.hitStop=0;step(s,{[trigger]:true});const hits=collectImpacts(s,{},1).filter(e=>e.source==='staff');assert.equal(s.stats.crewBursts,1);assert.equal(s.player.crewReady,false);assert.equal(hits.length,2);assert.deepEqual(hits.map(e=>e.staffType),['light','sound']);assert.ok(hits.every(e=>e.damage>0));s.player.x=s.boss.x-85;s.player.y=s.boss.y;s.player.comboIndex=3;s.player.chainTimer=.9;tick(s,{attack:true},1);assert.equal(s.stats.crewBursts,1);}});
test('actor finisher prepares one enhanced W with a delayed actual large piercing fifth arrow',()=>{const s=duel(0,'actor');s.player.comboIndex=3;s.player.chainTimer=.9;step(s,{attackPressed:true});tick(s,{},.4);assert.equal(s.player.adlibReady,true);s.player.x=500;s.player.y=500;s.boss.x=780;s.boss.y=500;s.hitStop=0;step(s,{skill:true});assert.equal(s.player.adlibReady,false);assert.equal(s.stats.adlibs,1);assert.equal(s.projectiles.length,4);assert.equal(s.followups.filter(f=>f.kind==='arrow').length,1);tick(s,{},.25);const big=s.projectiles.find(p=>p.empowered);assert.ok(big);assert.equal(big.damage,168);assert.equal(big.piercing,true);assert.equal(big.signature,'adlib-arrow');const hits=collectImpacts(s,{},.8).filter(e=>e.source==='adlib-arrow');assert.equal(hits.length,1);assert.ok(hits[0].damage>=168);assert.equal(hits[0].hitIndex,5);assert.equal(s.player.adlibReady,false);});
test('actor W retreats exactly 43.2 units without ordinary damage immunity',()=>{const s=duel(0,'actor');s.boss.x=1150;s.player.x=700;s.player.invuln=0;step(s,{skill:true});assert.equal(s.player.invuln,0);const x=s.player.x;tick(s,{},.15);assert.ok(Math.abs(x-s.player.x-43.2)<.001);const hurt=duel(0,'actor');hurt.player.invuln=0;hurt.hazards=[{type:'circle',x:700,y:500,radius:300,radiusY:200,active:true,life:1,damage:30}];step(hurt,{skill:true});assert.equal(hurt.player.hp,250);});
