test('actor E JUST dodge grants one next-Q finisher, consumes once and cannot loop within the buff',()=>{const s=duel(0,'actor');step(s,{buff:true});s.player.invuln=0;s.hazards=[{type:'circle',x:s.player.x,y:s.player.y,radius:500,radiusY:300,active:true,life:.2,damage:20}];step(s,{dodge:true});assert.equal(s.player.nextFinisherReady,true);assert.equal(s.player.methodRewardSpent,true);s.hazards=[];tick(s,{},.3);s.player.x=700;s.player.y=500;s.boss.x=780;s.boss.y=500;step(s,{attackPressed:true});assert.equal(s.player.comboIndex,4);assert.equal(s.player.nextFinisherReady,false);assert.equal(s.stats.methodFinishers,1);const hits=collectImpacts(s,{},.5).filter(e=>e.source==='method-strike');assert.equal(hits.length,3);assert.equal(hits.filter(e=>e.finisher).length,1);tick(s,{},.8);s.player.invuln=0;s.hazards=[{type:'circle',x:s.player.x,y:s.player.y,radius:500,radiusY:300,active:true,life:.2,damage:20}];step(s,{dodge:true});assert.equal(s.stats.justDodges,2);assert.equal(s.player.nextFinisherReady,false);});
test('stage reset clears every pending signature, crew hit and empowered projectile',()=>{const s=duel(0);s.boss.cueMarks=3;step(s,{buff:true,skill:true});assert.ok(s.followups.length>=3);startStage(s,1,{retry:true});const hp=s.boss.hp;tick(s,{},1);assert.equal(s.followups.length,0);assert.equal(s.boss.hp,hp);assert.equal(s.boss.cueMarks,0);assert.equal(s.player.crewReady,false);assert.equal(s.player.adlibReady,false);assert.equal(s.player.nextFinisherReady,false);});
test('dialogue follows actual engine events with bounded ordinary chatter and authoritative kit text',()=>{const s=duel(0);s.boss.hp=100000;s.boss.patternCooldown=999;const lines=new Map();for(let f=0;f<720;f++){step(s,{attack:true,skill:true,buff:true});for(const e of s.effects)if(e.type==='dialogue'&&!lines.has(e.id))lines.set(e.id,{...e,at:s.time});}const normal=[...lines.values()].filter(e=>e.priority<2);for(let i=1;i<normal.length;i++)assert.ok(normal[i].at-normal[i-1].at>=2.75);assert.ok(normal.some(e=>e.text==='오늘은 원 테이크로 갑니다.'));assert.ok(normal.length<=5);assert.equal(SKILL_KITS.actor.q.name,'검사 연기 — 대본 찢기');assert.equal(SKILL_KITS.director.e.name,'현장 통제 — 전 스태프 대기!');});
test('R preserves its actual damage roles and does not consume ordinary signature charges',()=>{for(const character of ['director','actor']){const s=duel(1,character);s.boss.hp=10000;s.player.hype=100;s.player.adlibReady=true;s.player.crewReady=true;s.player.buffTimer=0;step(s,{ultimate:true});finishCut(s);const first=s.effects.find(e=>e.type==='impact'),hits=[first,...collectImpacts(s,{},2.8)].filter((e,i,a)=>a.findIndex(x=>x.id===e.id)===i);assert.equal(hits.length,12);assert.equal(new Set(hits.map(e=>e.performanceRole)).size,character==='actor'?4:3);assert.equal(hits.at(-1).performanceRole,character==='actor'?'final':'slate-finish');assert.equal(s.stats.crewBursts,0);assert.equal(s.stats.adlibs,0);}});
test('takeover public guidance describes current action, timer meaning and normalized progress',()=>{for(const id of BOSSES.map(b=>b.id)){const s=openingPattern(id,3),h=s.hazards[0],g=getDomainGuide(s,h);assert.equal(g.timerLabel,id==='sukuna'?'진입 준비':'공격까지');assert.ok(g.progress>=0&&g.progress<=1);assert.ok(g.title.length>4);assert.ok(!g.instruction.includes('원가'));if(id==='sukuna'){assert.ok(g.instruction.includes('위아래'));assert.ok(!g.instruction.includes('고정'));}if(id==='mime')assert.match(g.instruction,/[①②③]/);}});

test('actor W hit-index metadata preserves its pre-signature hype gain per normal arrow',()=>{const s=duel(0,'actor');s.spotlight.x=50;s.spotlight.y=340;s.player.hype=0;step(s,{skill:true});tick(s,{},.5);assert.equal(s.stats.hits,5);assert.equal(s.stats.damageDealt,260);assert.ok(s.player.hype>=20.8&&s.player.hype<22);});


function walkTo(s,target,tolerance=4){return {left:target.x-s.player.x<-tolerance,right:target.x-s.player.x>tolerance,up:target.y-s.player.y<-tolerance,down:target.y-s.player.y>tolerance};}
function startBlades({character='director',variant=0,mirror=false,x=640,y=480,bossX=1000,bossY=480}={}){
 const s=createGame({stage:3,character,skipIntro:true});Object.assign(s.player,{x,y});s.player.cooldowns.dodge=99;
 Object.assign(s.boss,{x:bossX,y:bossY,attacks:variant===0?2:variant-1,phase:mirror?2:1,patternIndex:3,patternCooldown:0});step(s);return s;
}
function walkBladeRun(s,reaction=.35,policy='follow'){
 let key='',wait=0;const phases=new Set();
 for(let f=0;f<2400&&s.status==='playing'&&s.hazards.length;f++){
  const h=s.hazards[0],g=getDomainGuide(s,h),k=h.domainPhase+':'+h.phaseWarning+':'+h.bladeCheckpoint;
  if(k!==key){if(!key||h.phaseWarning||h.domainPhase===4&&h.bladeCheckpoint===1)wait=reaction;key=k;}
  let input={};if(!s.cinematic){wait-=1/60;if(wait<=0)input=policy==='follow'?walkTo(s,g.target):policy==='still'?{}:{[policy]:true};}
  if(h.active&&!h.phaseWarning)phases.add(h.domainPhase);step(s,input);
 }return {survived:s.status==='playing'&&!s.hazards.length,phases};
}
