function startPursuit({character='director',phase=1,x=640,y=482,bossX=1000,bossY=480}={}){
 const s=createGame({stage:3,character,skipIntro:true});Object.assign(s.player,{x,y});s.player.cooldowns.dodge=99;
 Object.assign(s.boss,{x:bossX,y:bossY,phase,takeoverCount:1,patternIndex:3,patternCooldown:0});step(s);return s;
}
function walkPursuitRun(s,reaction=.35,policy='follow',observe=()=>{}){
 let key='',wait=0;for(let f=0;f<1800&&s.status==='playing'&&s.hazards.length;f++){
  const h=s.hazards[0],g=getDomainGuide(s,h),k=h.domainPhase+':'+h.pursuitState;
  if(k!==key){if(h.pursuitState!=='flight')wait=reaction;key=k;}
  let input={};if(!s.cinematic){wait-=1/60;if(wait<=0)input=policy==='follow'?walkTo(s,g.target):policy==='still'?{}:policy==='circle'?{left:Math.cos(s.time*1.2)<-.2,right:Math.cos(s.time*1.2)>.2,up:Math.sin(s.time*1.2)<-.2,down:Math.sin(s.time*1.2)>.2}:policy.includes('-')?Object.fromEntries(policy.split('-').map(k=>[k,true])):{[policy]:true};}
  observe(s,h,g,input);step(s,input);
 }return s.status==='playing'&&!s.hazards.length;
}
