test('a real audition silhouette opens defense without granting dummy score; the marked fake never opens it',()=>{
 for(const correct of [true,false]){const s=extraPattern('mime'),a=s.audition;while(!a.active)step(s);const f=a.figures.find(f=>f.real===correct);s.player.x=f.x-65;s.player.y=f.y;s.player.facing=1;s.player.invuln=0;s.boss.x=1200;s.boss.y=340;const hp=s.player.hp;step(s,{attackPressed:true});assert.equal(a.selected,f.id);assert.equal(a.solved,correct);assert.equal(s.score,0);assert.equal(s.stats.damageDealt,0);assert.equal(s.stats.counterWindows,correct?1:0);assert.equal(s.player.hp<hp,!correct);assert.ok(a.figures.every(f=>Number.isFinite(f.x)&&Number.isFinite(f.stun)));}
});
test('audition requires the visible real choice and cannot farm score, counters or repeated outcomes',()=>{
 const s=extraPattern('mime'),a=s.audition;while(!a.active)step(s);const real=a.figures.find(f=>f.real);s.player.x=real.x-60;s.player.y=real.y;s.player.facing=1;step(s,{attackPressed:true});const windows=s.stats.counterWindows;tick(s,{attack:true},.4);assert.equal(s.stats.counterWindows,windows);assert.equal(s.stats.extraCompletions.mime,1);assert.equal(s.stats.auditionSuccesses,1);
 const cancel=extraPattern('mime');cancel.player.hype=100;step(cancel,{ultimate:true});assert.equal(cancel.audition,null);finishCut(cancel);assert.equal(cancel.stats.counterWindows,0);
});
test('replay copies the real recent path and never retargets those delayed circles',()=>{
 const s=duel(bossIndex('gojo'));s.player.x=320;s.player.y=500;tick(s,{right:true},1.4);s.boss.patternIndex=4;s.boss.patternCooldown=0;step(s);const hs=s.hazards.filter(h=>h.kind==='replay');assert.equal(hs.length,4);assert.ok(hs[0].x<hs[3].x-150);const points=hs.map(h=>[h.x,h.y]);tick(s,{up:true},.7);assert.deepEqual(hs.map(h=>[h.x,h.y]),points);assert.equal(s.stats.damageTaken,0);
});
test('Encore keeps its final delayed strike pending after the fast first three have passed',()=>{
 const s=extraPattern('sukuna');s.player.x=100;s.player.y=340;tick(s,{},1.8);assert.ok(s.hazards.some(h=>h.kind==='encore-finisher'&&!h.active));assert.ok(!s.hazards.some(h=>h.kind==='encore-slash'));assert.equal(s.stats.extraCompletions.sukuna,undefined);assert.match(getPatternGuide(s).instruction,/마지막 4타/);tick(s,{},1);assert.equal(s.stats.extraCompletions.sukuna,1);assert.equal(s.stats.extraSuccesses.sukuna,1);
});
test('surviving a takeover freezes the boss for one short counter opportunity, with no automatic score',()=>{
 const s=startBlades();assert.ok(walkBladeRun(s).survived);assert.equal(s.stats.counterWindows,1);assert.equal(s.boss.counterDuration,1.8);assert.ok(s.boss.counterRemaining>1.7);assert.equal(s.score,0);const x=s.boss.x,y=s.boss.y,attacks=s.boss.attacks;tick(s,{},1);assert.equal(s.boss.x,x);assert.equal(s.boss.y,y);assert.equal(s.boss.attacks,attacks);assert.match(getPatternGuide(s).instruction,/20%/);tick(s,{},.9);assert.equal(s.boss.counterRemaining,0);assert.equal(s.stats.counterWindows,1);
});
test('counter damage is exactly a temporary multiplier on actual HP and never prevents a fatal takeover hit',()=>{
 const a=duel(),b=duel();a.spotlight.x=b.spotlight.x=50;a.boss.counterRemaining=1.8;a.boss.counterDuration=1.8;step(a,{attackPressed:true});step(b,{attackPressed:true});assert.equal(a.stats.damageDealt,Math.round(25*.44*1.2));assert.equal(b.stats.damageDealt,Math.round(25*.44));assert.equal(a.stats.counterDamage,a.stats.damageDealt);fatalDomain(a);step(a,{ultimate:true});assert.equal(a.endReason,'domain');
 const capped=duel();capped.boss.counterRemaining=1.8;capped.boss.hp=3;step(capped,{attackPressed:true});assert.equal(capped.stats.damageDealt,3);assert.equal(capped.score,3);
});
test('cancelling a takeover warning or a rehearsal does not manufacture a survival counter',()=>{
 const s=openingPattern('sukuna',3);finishCut(s);s.player.hype=100;step(s,{ultimate:true});finishCut(s);tick(s,{},1);assert.equal(s.stats.counterWindows,0);
 const r=extraPattern('ignis');r.player.hype=100;step(r,{ultimate:true});finishCut(r);tick(r,{},1);assert.equal(r.rehearsal,null);assert.equal(r.stats.counterWindows,0);
});
test('numbered rehearsal lights are reachable from corners with .35s recognition and ordinary walking only',()=>{
 for(const character of ['director','actor'])for(const x of [76,640,1204])for(const y of [340,482,624]){
  const s=createGame({stage:0,character,skipIntro:true});s.player.x=x;s.player.y=y;s.player.cooldowns.dodge=99;s.boss.patternIndex=4;s.boss.patternCooldown=0;step(s);let index=-1,wait=0;
  for(let n=0;n<450&&s.rehearsal&&s.status==='playing';n++){const g=getPatternGuide(s);if(g?.kind==='rehearsal'&&g.index!==index){index=g.index;wait=.35;}wait-=1/60;step(s,wait<=0&&g?.target?walkTo(s,g.target):{});}
  assert.equal(s.stats.rehearsals,1,JSON.stringify({character,x,y}));assert.equal(s.player.hp,280);assert.equal(s.stats.dodges,0);assert.equal(s.stats.counterWindows,1);
 }
});
